import { CATEGORY_GROUP_LABEL, type CategoryGroupKey } from './apps/categories'

// Translated names of the 7 top-level app categories (the homepage chips, the comparison tool and
// the review-page block). Order: run-serve, chat-assistants, code-development, knowledge-retrieval,
// voice-audio, images-video, train-operate.
const GROUP_KEYS: CategoryGroupKey[] = ['run-serve', 'chat-assistants', 'code-development', 'knowledge-retrieval', 'voice-audio', 'images-video', 'train-operate']
const GROUP_LABELS: Record<string, string[]> = {
  de: ['Ausführen & Bereitstellen', 'Chat & Assistenten', 'Code & Entwicklung', 'Wissen & Retrieval', 'Sprache & Audio', 'Bilder & Video', 'Training & Betrieb'],
  fr: ['Exécution & serveur', 'Chat & assistants', 'Code & développement', 'Connaissances & recherche', 'Voix & audio', 'Images & vidéo', 'Entraînement & exploitation'],
  es: ['Ejecutar y servir', 'Chat y asistentes', 'Código y desarrollo', 'Conocimiento y recuperación', 'Voz y audio', 'Imágenes y vídeo', 'Entrenamiento y operación'],
  ja: ['実行・サーバー', 'チャット＆アシスタント', 'コード＆開発', 'ナレッジ＆検索', '音声＆オーディオ', '画像＆動画', 'トレーニング＆運用'],
  zh: ['运行与服务', '聊天与助手', '代码与开发', '知识与检索', '语音与音频', '图像与视频', '训练与运维'],
  pt: ['Executar e servir', 'Chat e assistentes', 'Código e desenvolvimento', 'Conhecimento e recuperação', 'Voz e áudio', 'Imagens e vídeo', 'Treinamento e operação'],
  ar: ['التشغيل والخدمة', 'الدردشة والمساعدون', 'البرمجة والتطوير', 'المعرفة والاسترجاع', 'الصوت والكلام', 'الصور والفيديو', 'التدريب والتشغيل'],
  ko: ['실행·서빙', '채팅·어시스턴트', '코드·개발', '지식·검색', '음성·오디오', '이미지·영상', '학습·운영'],
}

export function groupLabel(group: CategoryGroupKey, lang: Language | string): string {
  const labels = GROUP_LABELS[lang]
  return labels ? labels[GROUP_KEYS.indexOf(group)] : CATEGORY_GROUP_LABEL[group]
}

export function compareStrings(lang: Language | string): CompareStrings {
  return STRINGS[lang as Language] ?? (STRINGS.en as CompareStrings)
}

export function fmt(template: string, vars: Record<string, string | number>): string {
  return template.replace(/\{(\w+)\}/g, (_, k) => String(vars[k] ?? ''))
}
